<script setup lang="ts">
/**
 * A segmented field for a length of time (`design/components/duration-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/duration-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import {
  agentDuration,
  agentMember,
  commitDuration,
  durationDraft,
  durationKey,
  durationSegments,
  typeIntoDuration,
  type DurationUnit,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/duration-input.module.css'

export interface DurationInputMessages {
  /** What an empty count says as its value to assistive software. */
  empty: string
}

export interface DurationInputProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  defaultValue?: number | null
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * Sets the digits, the unit words and each count's name.
   */
  locale?: string
  /**
   * The most seconds a commit holds; none by default.
   */
  max?: number
  /**
   * The one word the member writes itself.
   */
  messages?: DurationInputMessages
  /**
   * The fewest seconds a commit holds; `0` by default.
   */
  min?: number
  /**
   * Posts the committed value as whole seconds, such as `"604800"`.
   */
  name?: string
  /**
   * Keeps the counts focusable, but arrows and digits do not edit.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * Which counts show, in any order; they are drawn largest first. Days, hours and minutes by
   * default.
   */
  units?: readonly DurationUnit[]
  /**
   * Whole seconds, and `null` for the empty field. `onChange` reports committed values: a step
   * as it fires, typed digits when focus leaves the field or on Enter, each held inside `min`
   * and `max`.
   */
  value?: number | null
}

defineOptions({ name: 'DurationInput', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<DurationInputProps>(), {
  ariaRequired: undefined,
  disabled: false,
  invalid: false,
  messages: () => ({ empty: 'Empty' }),
  readOnly: false,
  size: 'md',
})
const emit = defineEmits<{ change: [seconds: number | null] }>()
const uid = useId()
const browserLanguage = ref(undefined as string | undefined)
const draft = ref(
  durationDraft(props.value !== undefined ? props.value : (props.defaultValue ?? null), {
    units: props.units,
    min: props.min,
    max: props.max,
    locale: props.locale ?? browserLanguage.value ?? 'en-US',
  }),
)
const typed = ref('')
const reported = ref(
  (props.value !== undefined ? props.value : (props.defaultValue ?? null)) as number | null,
)
const field = useTemplateRef<HTMLElement>('field')
const language = computed(() => props.locale ?? browserLanguage.value ?? 'en-US')
const fieldOptions = computed(() => ({
  units: props.units,
  min: props.min,
  max: props.max,
  locale: language.value,
}))
const editable = computed(() => !props.disabled && !props.readOnly)
const segments = computed(() => durationSegments(draft.value, fieldOptions.value, props.messages))
const posted = computed(() => (props.value !== undefined ? props.value : reported.value))
const moveSegment = computed(() => (from: EventTarget | null, by: number): void => {
  if (!(from instanceof HTMLElement)) return
  const all = [
    ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
  ]
  all[all.indexOf(from) + by]?.focus()
})
const commit = computed(() => (next: ReturnType<typeof durationDraft>): void => {
  const result = commitDuration(next, reported.value, fieldOptions.value)
  draft.value = result.draft
  if (result.changed) {
    reported.value = result.value
    emit('change', result.value)
  }
})
const act = computed(
  () =>
    (action: ReturnType<typeof durationKey>, from: EventTarget | null): void => {
      if (action.kind === 'move') {
        typed.value = ''
        moveSegment.value(from, action.by)
      } else if (action.kind === 'type') {
        typed.value = action.typed
        draft.value = action.draft
        if (action.advance) moveSegment.value(from, 1)
      } else if (action.kind === 'step') {
        typed.value = ''
        commit.value(action.draft)
      } else if (action.kind === 'commit') {
        typed.value = ''
        commit.value(draft.value)
      }
    },
)
const segmentKeys = computed(
  () =>
    (event: KeyboardEvent, segment: ReturnType<typeof durationSegments>[number]): void => {
      const action = durationKey(
        draft.value,
        segment.unit,
        typed.value,
        event,
        {
          editable: editable.value,
          rtl: getComputedStyle(event.currentTarget as HTMLElement).direction === 'rtl',
        },
        fieldOptions.value,
      )
      if (action.kind === 'pass') return
      event.preventDefault()
      act.value(action, event.currentTarget)
    },
)
const segmentInput = computed(
  () =>
    (event: Event, segment: ReturnType<typeof durationSegments>[number]): void => {
      event.preventDefault()
      if (!editable.value) return
      const data = (event as InputEvent).data ?? ''
      for (const key of data) {
        const next = typeIntoDuration(
          draft.value,
          segment.unit,
          typed.value,
          key,
          fieldOptions.value,
        )
        typed.value = next.typed
        draft.value = next.draft
        if (next.advance) {
          moveSegment.value(event.currentTarget, 1)
          break
        }
      }
    },
)
const leave = computed(() => (event: FocusEvent): void => {
  const to = event.relatedTarget
  if (to instanceof Node && (event.currentTarget as HTMLElement).contains(to)) return
  typed.value = ''
  commit.value(draft.value)
})
const effect1 = () => {
  browserLanguage.value = globalThis.navigator?.language
}
onMounted(effect1)
const effect2 = () => {
  props.value !== undefined &&
    ((draft.value = durationDraft(props.value, fieldOptions.value)), (reported.value = props.value))
}
watch(() => props.value, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'DurationInput',
    element: () => field.value,
    state: () => ({
      value: posted.value,
      disabled: props.disabled,
      invalid: props.invalid,
      readonly: props.readOnly,
    }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (props.readOnly) throw new Error('The field is read-only.')
            commit.value(
              durationDraft(agentDuration(value, fieldOptions.value), fieldOptions.value),
            )
          })(),
      },
      clear: () =>
        (() => {
          if (props.readOnly) throw new Error('The field is read-only.')
          commit.value({})
        })(),
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <div
    ref="field"
    :class="styles.field"
    role="group"
    :id="id"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-disabled="disabled ? 'true' : undefined"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-readonly="readOnly ? '' : undefined"
    data-member="duration-input"
    @focusout="leave($event)"
  >
    <!-- segments -->
    <div :class="styles.segments">
      <template v-for="segment in segments" :key="segment.unit">
        <!-- quantity -->
        <div :class="styles.quantity">
          <!-- unit -->
          <span v-if="segment.wordFirst" :class="styles.unit" aria-hidden="true">
            {{ segment.word }}
          </span>
          <!-- segment -->
          <div
            :class="styles.segment"
            role="spinbutton"
            :id="`${uid}-${segment.unit}`"
            :aria-label="segment.name"
            :aria-labelledby="
              ariaLabelledby ? `${ariaLabelledby} ${uid}-${segment.unit}` : undefined
            "
            :aria-describedby="ariaDescribedby"
            :aria-valuenow="segment.value"
            :aria-valuemin="segment.min"
            :aria-valuemax="segment.max"
            :aria-valuetext="segment.valueText"
            :aria-required="ariaRequired ? 'true' : undefined"
            :aria-readonly="readOnly ? 'true' : undefined"
            :aria-disabled="disabled ? 'true' : undefined"
            :aria-invalid="invalid ? 'true' : undefined"
            :contenteditable="editable ? 'true' : undefined"
            inputmode="numeric"
            spellcheck="false"
            :tabindex="disabled ? undefined : '0'"
            :data-segment="segment.unit"
            :data-placeholder="segment.placeholder ? '' : undefined"
            :data-disabled="disabled ? '' : undefined"
            @focus="typed = ''"
            @keydown="segmentKeys($event, segment)"
            @beforeinput="segmentInput($event, segment)"
          >
            {{ segment.text }}
          </div>
          <!-- unit -->
          <span v-if="!segment.wordFirst" :class="styles.unit" aria-hidden="true">
            {{ segment.word }}
          </span>
        </div>
      </template>
    </div>
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="posted === null ? '' : String(posted)"
      :disabled="disabled ? true : undefined"
    />
  </div>
</template>
